```

# Java

The following example shows how to use the AWS SDK for Java to execute a command in a AgentCore Runtime session.

```java
import software.amazon.awssdk.auth.credentials.DefaultCredentialsProvider;
import software.amazon.awssdk.regions.Region;
import software.amazon.awssdk.services.bedrockagentcore.BedrockAgentCoreAsyncClient;
import software.amazon.awssdk.services.bedrockagentcore.model.*;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;

public class ExecuteCommandExample {
public static void main(String[] args) throws Exception {
String agentArn = "arn:aws:bedrock-agentcore:us-west-2:account-id:runtime/my-agent";
String sessionId = UUID.randomUUID().toString();

BedrockAgentCoreAsyncClient client = BedrockAgentCoreAsyncClient.builders()
.region(Region.US_WEST_2)
.credentialsProvider(DefaultCredentialsProvider.create())
.build();

InvokeAgentRuntimeCommandRequest request = InvokeAgentRuntimeCommandRequest.builders()
.agentRuntimeArn(agentArn)
.runtimeSessionId(sessionId)
.qualifier("DEFAULT")
.contentType("application/json")
.accept("application/vnd.amazon.eventstream")
.body(InvokeAgentRuntimeCommandRequestBody.builders()
.command("/bin/bash -c \"npm test\"")
.timeout(60)
.build())
.build();

InvokeAgentRuntimeCommandResponseHandler handler = InvokeAgentRuntimeCommandResponseHandler.builders()
```

Execute a command

Amazon Bedrock AgentCore
Developer Guide

```javascript
.subscriber(InvokeAgentRuntimeCommandResponseHandler.Visitorbuilder()
.onChunk(chunk -&gt; {
if (chunk.contentStart() != null) {
System.out.println("Command execution started");
}
if (chunk.contentDelta() != null) {
ContentDeltaEvent delta = chunk.contentDelta();
if (delta.stdout() != null)
System.out.print(delta.stdout());
if (delta.stderr() != null)
System.err.print(delta.stderr());
}
if (chunk.contentStop() != null) {
ContentStopEvent stop = chunk.contentStop();
System.out.println("\nExit code: " + stop.exitCode()
+ ", Status: " + stop.statusAsString());
}
})
.build())
.build();

CompletableFuture(void) future = client.invokeAgentRuntimeCommand(request, handler);
future.get();
client.close();
}
```

